DBR_COLS = ["ID", "Data", "Rule Description", "Applies to / Use Cases"]
NF = ""
DBR = [
["DBR-01","Full name","String, 2–50 characters; Unicode letters including Vietnamese diacritics, spaces, apostrophe and hyphen; no digits or other symbols; trimmed on save.","Customer, Employee"],
["DBR-02","Password","Masked, 8–64 characters, at least one letter and one digit, different from the current password and equal to its confirmation; stored only as a BCrypt hash, never displayed or logged. A temporary password generated at the counter has 10 characters with at least one letter and one digit and no look-alike characters (CBR-31).","Account"],
["DBR-03","Verification code","Exactly 6 digits, single use, valid P-15 minutes; a new code cancels the previous one.","Account, VerificationCode"],
["DBR-04","Date of birth","Not in the future; age ≤ 100.","Customer, Employee"],
["DBR-05","Reason text","5–500 characters (rejection, cancellation, deletion, freeze, leave, late approval, refund note, acceptance note).","All reason fields"],
["DBR-06","Money","Integer VND > 0, no decimals; a discount never exceeds the price. Catalogue prices are 10,000–500,000,000 VND in multiples of 1,000 (BR-107).","Package, Order, Transaction, Voucher"],
["DBR-07","Percentages","Integers: VAT 0–20, PT commission 0–100, percentage discount 1–100.","SystemConfig, Employee, Voucher"],
["DBR-08","Images","JPG or PNG, max 5 MB, max 2000 × 2000 px.","Avatar, check-in photo, facility image, maintenance images, blog cover"],
["DBR-09","System codes","Customer code KH-nnnn, employee code NV-nnnn, order code DH-yyyy-nnnn, maintenance request code BT-nnnn: generated by the system, unique, and never changed. Screens may show a role prefix instead of NV- (GBR-39).","Customer, Employee, Order, MaintenanceRequest"],
["DBR-10","Voucher code","4–20 characters, uppercase letters A–Z and digits, unique across all vouchers; not editable after first use.","Voucher"],
["DBR-11","Package name","3–50 characters, unique among packages on sale.","Package"],
["DBR-12","Time values","HH:mm; closing time later than opening time; PT slot start times on a 15-minute grid; an operating-hour exception date is today or later and unique.","TimeSlot, SystemConfig, OperatingHourException"],
["DBR-13","Date ranges","From ≤ To. A freeze starts tomorrow at the earliest and lasts no longer than P-02 or the days remaining on the package. Leave ranges follow DBR-74.","FreezeRecord, Voucher, LeaveRequest, report filters"],
["DBR-14","Quantities","Integers ≥ 1: voucher total usage (never below the used count), usage per customer (empty = unlimited), PT package estimated sessions 1–255. Facility quantities are computed from equipment items, never typed (BR-104).","Voucher, Package, Facility"],
["DBR-15","Text lengths","Package description ≤ 255; package benefits one per line; feedback 10–1000; private note 1–2000; workout / meal plan ≤ 10 000; blog title 5–200, content ≤ 20 000; notification title 5–100, content 10–500; maintenance description 10–500, affected-items note ≤ 100, Manager note ≤ 500; facility group name 3–100, unit label ≤ 15; equipment item code 2–20, label 1–50, placement note ≤ 100; body-measurement note ≤ 200; reschedule note ≤ 500; transfer reference ≤ 50; exercise search ≤ 50.","Package, Feedback, PrivateNote, TrainingPlan, BlogPost, Notification, MaintenanceRequest, Facility, EquipmentItem, BodyMeasurement, Session"],
["DBR-16","Event timestamps","Business event times (paid, cancelled, checked in, reviewed, closed, read…) are written when the event happens and never edited.","All entities"],
["DBR-17","Phone numbers","A phone number must follow the Vietnamese format: 10 digits, starting with 0, with a valid 3-digit carrier prefix (P-16).","UC-01, UC-03, UC-04, UC-05, UC-07, UC-13, UC-16, UC-20"],
["DBR-18","Email","An email must follow the format name@domain and be at most 100 characters.","UC-01, UC-03, UC-04, UC-05, UC-07, UC-13, UC-16, UC-20"],
["DBR-19","Package.Duration","A day pass lasts exactly 1 day; a membership package 1–36 months; a PT package 1–12 months (database limits). The catalogue form offers membership durations of 1, 3, 6, 12, 24 or 36 months and PT durations of 1, 3, 6 or 12 months; a package created earlier with another duration (e.g. 9 months, or a 2-month PT package) can still be sold but cannot be put back on sale after being stopped. End dates are computed by calendar month (GBR-03), never as 30 days.","UC-10, UC-20, UC-21, UC-22"],
["DBR-20","TimeSlot","A PT slot lasts P-06 minutes (default 90) when it is published; one slot on a PT's calendar holds one session. A slot keeps the length it was published with even if P-06 changes later.","UC-21, UC-30, UC-37"],
["DBR-21","Package.Package Type","There are two kinds of PT package: single (PTSingle) and couple (PTCouple); SingleSession is a one-session package.","UC-10, UC-21"],
["DBR-22","Person.Phone","A phone number is stored on Person and must not duplicate any other active Person, customer or staff alike. A Person is active while at least one of its roles (customer profile or employee record) is not Inactive. Every Person has a phone number except a Dependent profile (DBR-24), because the phone number is what the Receptionist and the Admin use to find an existing Person (CBR-19, CBR-114).","UC-05, UC-07, UC-16, UC-20, UC-IDENT"],
["DBR-23","Person.Email","An email is stored on Person and must not duplicate any other active Person (DBR-22). It is mandatory for every Person who has a login account and for every Self customer profile (CBR-18); it is not used for a Dependent profile (DBR-26). A rejected duplicate only says the email is already in use, never whose it is.","UC-04, UC-05, UC-07, UC-16, UC-20, UC-IDENT"],
["DBR-24","Customer (dependent) — guardian fields","A Dependent customer profile has no phone of its own on Person; it is reached through the guardian phone numbers recorded on the profile, which several dependants may share — siblings may use the same guardian number — as long as the guardian's full name and relationship are recorded.","UC-16, UC-20"],
["DBR-25","Customer (dependent) — guardian fields","A Dependent profile records the guardian's full name (2–50 characters), relationship (up to 30 characters) and up to two guardian phone numbers, so a child can be reached through either parent.","UC-16, UC-20"],
["DBR-26","Customer.Email (dependent)","A Dependent profile has no email and no account.","UC-16, UC-20"],
["DBR-27","Person.Phone","A staff member and a customer who are the same individual share one Person record, so they have one phone number and one email; there is never a separate staff phone or email list.","UC-07, UC-13"],
["DBR-28","Phone / email of inactive records","When a role becomes Inactive (customer profile deleted, employee resigned) while the Person still has another role that is not Inactive, the Person keeps its phone number and email. When every role of the Person is Inactive, the phone number and email are released immediately and the person can get a new profile without waiting (CBR-23).","UC-05, UC-07, UC-13, UC-16"],
["DBR-29","Person.Email","Merged into DBR-23.","—"],
["DBR-30","Person","One Person, several roles, one account: the same individual working as staff and training as a customer keeps one Person, one phone number, one email and one login account (DBR-65).","UC-01, UC-07, UC-16"],
["DBR-31","Customer (walk-in)","A walk-in customer still needs a profile: Self profiles need full name, date of birth, phone number and email (CBR-118); Dependent profiles need the guardian fields.","UC-16, UC-20"],
["DBR-32","TimeSlot ↔ Session","A slot of a PT is assigned to one customer only, or to one pair of customers for a couple package; it has at most one Scheduled session.","UC-21, UC-35, UC-37"],
["DBR-33","TimeSlot","Slots of a PT must not overlap (checked when publishing, holding and moving sessions); apart from that the PT decides whether slots are back-to-back or spaced out.","UC-21, UC-30, UC-35"],
["DBR-34","Customer.Status","A customer profile has exactly five states: New, Active, Frozen, Expired, Inactive.","UC-16, UC-19, UC-41"],
["DBR-35","Customer.Status","Inactive is a final state; an Inactive profile never returns to any other state.","UC-16"],
["DBR-36","TimeSlot.Status","A PT slot has four states: Free, Held, Booked, Withdrawn. A slot becomes Held when an order reserves it: an online single-session order until its payment deadline (P-09), or a PT-sale hold for 15 minutes (HoldExpiresAt, BR-93). When the order is Paid the slot becomes Booked. When the order is cancelled, released or expires, the slot returns to Free (a slot created only for that hold is deleted). When a session is moved or cancelled by the PT, its old slot returns to Free. A Free slot that the PT removes becomes Withdrawn and is kept; publishing the same start time again reopens it (BR-94, BR-95).","UC-21, UC-30, UC-35, UC-37, UC-PAY"],
["DBR-37","Session.Status","A session has four states: Scheduled, CheckedIn, Missed, Cancelled. Missed always has a reason (NoCheckIn, NoMembership, MembershipFrozen); Cancelled always has a type (ByPt, ByCustomer — historical, GymClosed, PackageExpired).","UC-31, UC-32, UC-35, UC-36"],
["DBR-38","Session.Status","A session in a final state (CheckedIn, Missed, Cancelled) cannot be changed by anyone. Only JOB-04 moves a session from Scheduled to CheckedIn or Missed.","UC-31, UC-32"],
["DBR-39","Order.Status","An order has three states: Pending, Paid, Cancelled. There is no refunded state — refunds are paid outside the system and only confirmed on the transaction (BR-81).","UC-20, UC-21, UC-22, UC-24, UC-25, UC-26, UC-PAY"],
["DBR-40","Order.Status","An order moves only along Pending → Paid, Pending → Cancelled, and Paid → Cancelled (only under CBR-11). Cancelled is final.","UC-20, UC-21, UC-22, UC-PAY"],
["DBR-41","Transaction.Status","Every payment attempt for an order is recorded as a transaction with four states: Pending, Success, Failed, Expired. One order may have several transactions.","UC-20, UC-21, UC-22, UC-24, UC-26, UC-PAY"],
["DBR-42","Transaction","An order has at most one Success transaction and at most one Pending transaction at any time. A Paid order gets no further transactions.","UC-PAY"],
["DBR-43","Order.Cancel Type","A cancelled order records its cancellation type: payment deadline passed (CBR-70), replaced by a new order (CBR-71), invalid payment (CBR-72) or cancelled by the Receptionist (CBR-11, and PT-sale holds released or expired — BR-93, with the reason text).","UC-20, UC-21, UC-24, UC-25, UC-26"],
["DBR-44","LeaveRequest.Status","A leave request has three states: Pending, Approved, Rejected. A Pending request withdrawn by its owner is removed (BR-83).","UC-14, UC-15"],
["DBR-45","MaintenanceRequest.Status","A maintenance request has four states: Open, In Progress, Rejected, Closed.","UC-28, UC-29"],
["DBR-46","MaintenanceRequest.Status","A maintenance request moves only along Open → In Progress → Closed, or Open → Rejected; no step is skipped. In Progress records the reviewer, review time, the \"set under maintenance\" choice and an optional Manager note; Rejected records a reason of at least 5 characters; Closed records the closing Receptionist, time and an acceptance note of 5–500 characters.","UC-28, UC-29"],
["DBR-47","isMember (derived)","A customer whose state is Active, Frozen or Expired is a member (isMember = TRUE), including someone who has only ever bought a day pass. Once a member, always a member; whether the person can currently use the gym is expressed by canUseService.","UC-16, UC-41"],
["DBR-48","canUseService (derived)","canUseService on a date = the customer can use the gym on that date as defined in CBR-117 (a Membership or DayPass covering the date, not frozen). A PT package or remaining PT sessions never make it TRUE (CBR-58).","UC-19, UC-36, UC-37, UC-41"],
["DBR-49","Customer.Customer Type","A profile without its own phone number, using a guardian's number, is a Dependent profile.","UC-16, UC-20"],
["DBR-50","Order snapshots","When an order is created, the current package name, description, benefits, price and VAT rate are copied into the order; later catalogue changes never affect it (CBR-09).","UC-20, UC-21, UC-22"],
["DBR-51","Subscription.End Date","New end date = old end date + the number of days actually frozen.","UC-18"],
["DBR-52","Subscription.Start / End Date","The start date of a new membership package or day pass follows CBR-119: the day after the current membership ends if it has not expired; otherwise today or a chosen date up to 7 days ahead (the customer may move an unused online package once). End date = start date + package duration (DBR-19, GBR-03); a day pass ends on its start date.","UC-20, UC-22, UC-41"],
["DBR-53","Subscription.Generated Session Count","PT packages are sold by term, not by number of sessions. The session count of an order is the number of sessions held at sale (BR-40) and is fixed when the order is Paid. Catalogues and public pages show only the estimated session count of the package.","UC-10, UC-21"],
["DBR-54","Couple subscription quota","A couple PT package shares one quota between both members.","UC-21, UC-36"],
["DBR-55","Shift.Expected Cash","Expected cash at shift close = the sum of Success cash transactions recorded in that shift for orders that are not Cancelled."+NF,"UC-25, UC-PAY"],
["DBR-56","Revenue (derived)","Revenue = the sum of Success transactions of orders that are not Cancelled. Refunds made outside the system are not deducted.","UC-26, UC-46"],
["DBR-57","Order.VAT Amount","Amount payable = package price at purchase − discount; VAT amount = Amount payable × VAT% ÷ (100 + VAT%), rounded to the dong and stored on the order at creation; Pre-tax amount = Amount payable − VAT amount.","UC-20, UC-21, UC-24, UC-26, UC-46, UC-PAY"],
["DBR-58","Session.Commission Amount","PT commission of a session = round(session value × commission rate of the PT teaching it ÷ 100), stored on the session when it is created and recomputed only on a transfer (BR-68).","UC-21, UC-35, UC-46"],
["DBR-59","Session.Session Value","Session value = round(amount paid for the order ÷ number of sessions generated for that order) (BR-40); PT packages have no discount (CBR-76).","UC-21, UC-37, UC-46"],
["DBR-60","Remaining staff per shift (derived)","Remaining staff of a shift (per role, PT / Receptionist) = Working employees of that role − those with Approved leave overlapping the shift. Every Working employee is assumed to work both shifts (no roster).","UC-15"],
["DBR-61","Subscription snapshots","At sale the subscription stores the freeze allowance (P-01, membership only), the swap allowance MaxSwapsSnapshot = P-08 × package months (PT packages) and, for PT packages, the PT in charge and the fixed start time (the most frequent session time).","UC-18, UC-21"],
["DBR-62","TrainingPlan","At most one active plan per (PT, customer, plan type — workout or meal). A deleted plan does not count, so a new one may be written after deletion.","UC-34"],
["DBR-63","StaffAttendance","At most one record per (employee, work date, shift type); check-out time must be later than check-in time. Modelled only — staff timekeeping is out of scope for this release.","Employee"],
["DBR-64","Person.Avatar","Avatar: JPG or PNG, max 5 MB, max 2000 × 2000 px (DBR-08). It is stored on Person, shown for every role of that Person, and is for display only (CBR-37). When there is no avatar (or it is removed) the initials of the first and last name are shown.","UC-04"],
["DBR-65","Person roles & Account","A Person has at most one customer profile that is not Inactive, at most one employee record with status Working, and at most one login Account that serves every non-Inactive role; an Inactive role does not block creating a new role of the same kind (CBR-114).","UC-01, UC-05, UC-07, UC-13, UC-16"],
["DBR-66","Feedback","Feedback content is 10–1000 characters. A feedback may rate one PT with 1–5 stars for a month (rating month = first day of that month); without a PT there is no rating.","UC-42, UC-43"],
["DBR-67","Feedback (PT rating)","A customer has at most one rating per PT per month. Rating the same PT again in the same month overwrites the stars and content and makes the feedback unread again (CBR-107).","UC-42, UC-43"],
["DBR-68","PT monthly rating (derived)","Monthly average of a PT = total stars ÷ number of customers who rated that PT in the month, truncated to two decimals (4.999 shows 4.99); shown to the PT with a short encouragement text.","UC-32"],
["DBR-69","PT monthly rating (display)","The average is shown only when at least P-22 (default 3) customers rated the PT that month; otherwise the PT sees \"no rating yet\" or \"not enough ratings yet\".","UC-32"],
["DBR-70","BodyMeasurement","At most one measurement per customer per date (BR-87); weight 20–300 kg, height 100–250 cm, body fat 3–70 %, muscle 10–70 %, waist 40–200 cm, one decimal; BMI is derived, not stored (BR-88).","UC-49"],
["DBR-71","Exercise","Cache of wger exercises: the id is the wger id; name and description in English (HTML removed); CategoryId, MuscleIds and EquipmentIds are wger codes, not foreign keys; image URL optional; SyncedAt = time of the last download.","UC-48"],
["DBR-72","EquipmentItem","ItemCode is unique in the whole system; ItemLabel is unique within its facility group; status Available, UnderMaintenance or Retired (Retired is final).","UC-27, UC-28"],
["DBR-73","MaintenanceRequest","Each request concerns exactly one equipment item and has a unique code BT-nnnn, a priority (default Normal), an incident type (default NotWorking), a description, a warning-tag flag (default no) and optional images.","UC-28, UC-29"],
["DBR-74","LeaveRequest range","FromDate ≤ ToDate, at most 31 days, within one calendar year; Days > 0 (both ends included; a morning or afternoon shift counts 0.5 day); a half-day shift only for a one-day request. A request split under CBR-121 is stored as two rows sharing one leave group id.","UC-14, UC-15"],
["DBR-75","Package.UnlocksExerciseLibrary","Set per package (default no). When set, the package's benefit list automatically shows \"Unlocks the Exercise Library\" on the home page and on package selection.","UC-06, UC-10, UC-22, UC-48"],
["DBR-76","Notification / NotificationRecipient","A notification has a title of 5–100 and content of 10–500 characters, an audience and a sent time; system notifications have no sender and audience Individual. Each recipient row stores ReadAt; \"read\" is derived from ReadAt, not stored.","UC-44, UC-50"],
["DBR-77","Subscription (online start date)","An online membership subscription whose start date was moved by the customer (CBR-119) cannot be moved again; the change is audited.","UC-41"],
]
